package vn.edu.eaut.lab7.controller;import jakarta.servlet.*;import jakarta.servlet.annotation.*;import jakarta.servlet.http.*;import vn.edu.eaut.lab7.model.*;import vn.edu.eaut.lab7.repository.*;import java.io.*;
@WebServlet("/sach")public class SachController extends HttpServlet{private final SachRepository r=new SachRepository();protected void doGet(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{String a=q.getParameter("action");if("new".equals(a)){q.getRequestDispatcher("/views/sach/form.jsp").forward(q,p);return;}if("edit".equals(a)||"detail".equals(a)){q.setAttribute("sach",r.findById(Integer.parseInt(q.getParameter("id"))));q.getRequestDispatcher("/views/sach/"+("edit".equals(a)?"form":"detail")+".jsp").forward(q,p);return;}if("delete".equals(a)){r.delete(Integer.parseInt(q.getParameter("id")));p.sendRedirect(q.getContextPath()+"/sach");return;}q.setAttribute("danhSach",r.search(q.getParameter("keyword")));q.getRequestDispatcher("/views/sach/list.jsp").forward(q,p);}protected void doPost(HttpServletRequest q,HttpServletResponse p)throws IOException{int id=q.getParameter("id")==null||q.getParameter("id").isBlank()?0:Integer.parseInt(q.getParameter("id"));Sach x=new Sach(id,q.getParameter("maSach"),q.getParameter("tenSach"),q.getParameter("tacGia"),q.getParameter("nhaXuatBan"),Integer.parseInt(q.getParameter("namXuatBan")));if(id==0)r.add(x);else r.update(x);p.sendRedirect(q.getContextPath()+"/sach");}}
